-- ═══ KIỂM TRA ═══
SELECT '--- USERS ---' as info;
SELECT id, username, full_name FROM users WHERE role = 'CLIENT' ORDER BY username;
SELECT '--- ORDERS ---' as info;
SELECT COUNT(*) as "Tong don", status FROM orders GROUP BY status ORDER BY status;
SELECT '--- TOP SAN PHAM ---' as info;
SELECT snapshot_product_name, SUM(quantity) as so_luong, SUM(oi.sub_total) as doanh_thu
FROM order_items oi JOIN orders o ON oi.order_id = o.id
WHERE o.status != 'CANCELLED'
GROUP BY snapshot_product_name ORDER BY so_luong DESC LIMIT 10;
